-- tf-bankrec-r3: put the reconciliation TEST data of the isolated test bed back exactly as it was before the r3 verification
-- (snapshot sql/before-r3-snapshot/, taken from avenir_restore_verify_20261011 before r3 was installed). ISOLATED TEST BED ONLY.
-- Use together with: python apply.py rollback <avenir_rv root> (r3 made no schema change; schema stays at version 2).
-- Replaces only: the brc_ tables' rows, the dummy ledger rows 99980000-99989999 (the dummy posting entry included), the TEST bank
-- accounts and TEST ledger accounts, the brc_ settings in tpd_meta; removes the TEST login TestRecDual and its TEST group.
-- The audit trail is kept (append-only); a row records this reset.
-- Snapshot md5 (first 12): brc_account_map 2923da9cf908, brc_statement 5c7c918f76cd, brc_line 7064a08d2733, brc_fx_rate e69712104aa9, brc_match 0d0aff90ffb8, brc_match_item 237ffac08b47, brc_mark 1dabec8bc613, brc_mark_event 0e02c5ea3dcf, brc_claim 50d2ca13ef81, brc_transfer 4a72c2f79ccf, brc_opening b54bf54d1c43, brc_correction c7cf30a18fde, brc_day dd7f1d174a30, account_runing 90bb61615bdd, tpd_bank_account d654d15fa599, account_posting 444487e8802e, tpd_meta dfeb58ca6453

-- Guard: stops (error 1048) unless this is the isolated test-bed database at schema version 2.
DROP TEMPORARY TABLE IF EXISTS brc_r3_guard;
CREATE TEMPORARY TABLE brc_r3_guard (ok TINYINT NOT NULL);

DELETE FROM `brc_account_map` ;
DELETE FROM `brc_statement` ;
DELETE FROM `brc_line` ;
DELETE FROM `brc_fx_rate` ;
DELETE FROM `brc_match` ;
DELETE FROM `brc_match_item` ;
DELETE FROM `brc_mark` ;
DELETE FROM `brc_mark_event` ;
DELETE FROM `brc_claim` ;
DELETE FROM `brc_transfer` ;
DELETE FROM `brc_opening` ;
DELETE FROM `brc_correction` ;
DELETE FROM `brc_day` ;
DELETE FROM `account_runing` WHERE ID BETWEEN 99980000 AND 99989999;
DELETE FROM `tpd_bank_account` WHERE label LIKE 'TEST % account (dummy)';
DELETE FROM `account_posting` WHERE L_Code IN ('1-6-8-29901','1-6-8-29902','1-6-8-29903','1-6-8-29904','2-9-99-29909');
DELETE FROM `tpd_meta` WHERE k LIKE 'brc%';
-- the TEST login added for the dual-role test
DELETE FROM user_privileges WHERE group_id IN (SELECT id FROM (SELECT id FROM group_profile WHERE type = 'TEST Reconciliation preparer + reviewer (test)') g);
DELETE FROM user_acc_tbl WHERE user = 'TestRecDual';
DELETE FROM employee WHERE Name = 'TEST Reconciliation dual-role tester (test)';
DELETE FROM group_profile WHERE type = 'TEST Reconciliation preparer + reviewer (test)';
DROP TEMPORARY TABLE IF EXISTS brc_r3_guard;
SELECT (SELECT COUNT(*) FROM brc_day) AS daily_records, (SELECT COUNT(*) FROM brc_correction) AS corrections, (SELECT COUNT(*) FROM account_runing WHERE ID BETWEEN 99980000 AND 99989999) AS dummy_rows, (SELECT COUNT(*) FROM user_acc_tbl WHERE user = 'TestRecDual') AS dual_login;
